using System;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Web.Script.Serialization;
class TavernTimeChecks {
 [STAThread]static void Main(){var save=new Save();var random=new Random(7);var t=TavernTime.State(save);if(t.phase!="morning"||t.day!=1)throw new Exception("old save default");TavernTime.Advance(save,random);if(t.phase!="dusk")throw new Exception("dusk");TavernTime.Advance(save,random);if(t.phase!="night")throw new Exception("night");TavernTime.Advance(save,random);if(t.phase!="morning"||t.day!=2)throw new Exception("next day");var json=new JavaScriptSerializer();var restored=json.Deserialize<Save>(json.Serialize(save));if(restored.tavernTime.day!=2||restored.tavernTime.weather!=t.weather)throw new Exception("persistence");var weather=new System.Collections.Generic.HashSet<string>();for(int i=0;i<100;i++){TavernTime.Advance(save,random);weather.Add(t.weather);}if(weather.Count!=3||save.rogue.coins!=0||save.tavernBusiness!=null)throw new Exception("weather/rewards");save.tavernTime.weather="fog";if(TavernTime.State(save).weather!="clear")throw new Exception("legacy fog migration");
  var flags=BindingFlags.NonPublic|BindingFlags.Instance;using(var game=new Game()){game.Show();var gs=(Save)typeof(Game).GetField("save",flags).GetValue(game);gs.tavernTime=new TavernTimeState{phase="night",weather="rain",day=2};typeof(Game).GetMethod("ShowTavernHub",flags).Invoke(game,null);var content=(Control)typeof(Game).GetField("content",flags).GetValue(game);var surface=content.Controls.OfType<CardRewardSurface>().Single();var clock=surface.Controls.OfType<TavernClock>().Single();foreach(var size in new[]{new Size(800,500),new Size(1280,780),new Size(1920,1080)}){game.Size=size;Application.DoEvents();if(!surface.ClientRectangle.Contains(clock.Bounds)||clock.Right<surface.Width-25||clock.Bottom<surface.Height-25)throw new Exception("clock placement");}using(var bmp=new Bitmap(surface.Width,surface.Height)){surface.DrawToBitmap(bmp,surface.ClientRectangle);bmp.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tavern-clock-night-rain.png"));}}
  string frames=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"clock-animation-frames");Directory.CreateDirectory(frames);int frame=0;using(var form=new Form{ClientSize=new Size(480,522)})using(var dial=Image.FromFile(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets/ui/tavern-time-clock-dial.png"))){var clock=new TavernClock{Dock=DockStyle.Fill,Art=dial,Time=new TavernTimeState()};form.Controls.Add(clock);form.Show();foreach(var phase in new[]{"morning","dusk","night"}){clock.Time.phase=phase;bool done=false;double start=clock.DisplayAngle,last=start;int samples=0;clock.AnimateNext(()=>{done=true;});var timer=System.Diagnostics.Stopwatch.StartNew();while(!done&&timer.ElapsedMilliseconds<3000){Application.DoEvents();if(clock.Animating){double angle=clock.DisplayAngle;if(angle<last||angle>start+120.01)throw new Exception("non-monotonic hand");last=angle;samples++;}using(var bmp=new Bitmap(480,522)){clock.DrawToBitmap(bmp,clock.ClientRectangle);bmp.Save(Path.Combine(frames,"frame-"+(frame++).ToString("D4")+".png"));}System.Threading.Thread.Sleep(16);}if(!done||samples<20||last<start+110)throw new Exception("incomplete animation");}clock.Dispose();}
  Console.WriteLine("PASS old-save/fog migration, 3-phase/day cycle, saved weather, 3 random weathers, no rewards, 3 window sizes; 3 clockwise animations, intermediate frames and completion");
 }
}
